import json
import re
import html

sources = json.load(open('source.json'))
refs = json.load(open('reference-targets.json'))
answers = []
for s in sources:
    a = {k: s[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    a.update({k: s['previous_draft'][k] for k in ('proposed_xml', 'reason', 'review_notes')})
    a['status'] = 'rewrite_draft'
    answers.append(a)

def reduction(i, removed):
    answers[i].update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)

def impact(i, classification, assessment, limitations, burdens, effects):
    answers[i]['substantive_impact'] = dict(version=1, classification=classification, assessment=assessment, scope_limitations=limitations, new_burdens_review=burdens, effects=effects)

def effect(kind, measure, description, before, after, unit, people, transition, replacement, sq, pq):
    return dict(kind=kind, measure_id=measure, description=description, before=before, after=after, unit=unit, affected_population=people, conditions_and_transition=transition, replacement_or_new_burdens=replacement, source_quote=sq, proposed_quote=pq)

answers[0]['proposed_xml'] = """<p>Un accord de branche ou un accord collectif conclu entre les organisations syndicales de salariés et d'employeurs signataires de l'accord constitutif d'un opérateur de compétences interprofessionnel peut définir les modalités de continuation et de financement, pour six mois au plus, des actions d'évaluation et d'accompagnement et des enseignements mentionnés à l'article L. 6325-13. Cette faculté bénéficie aux personnes dont le contrat de professionnalisation comportant une action de professionnalisation au sens de l'article L. 6325-11 a été rompu, quelle que soit la durée initialement prévue pour cette action et quelle que soit la partie à l'initiative de la rupture.</p>
<p>À compter de l'entrée en vigueur de la loi portant la présente réforme, ni une durée initiale inférieure à douze mois ni l'initiative de la rupture par le bénéficiaire ne peuvent, à elles seules, exclure celui-ci du dispositif conventionnel de continuation et de financement. Cette règle s'applique aux continuations décidées à compter de cette entrée en vigueur, même après une rupture antérieure, et à la durée restant à courir des continuations en cours, sans recommencer la durée maximale de six mois. Les financements accordés et les droits acquis sont conservés.</p>
<p>Cette faculté reste ouverte lorsque la professionnalisation est organisée dans un contrat unique à durée indéterminée. La durée de continuation de la formation ne fixe pas le terme d'un emploi et n'autorise ni la conclusion ni le renouvellement d'un contrat à durée déterminée après l'entrée en vigueur de la loi instituant le contrat unique.</p>"""
answers[0]['reason'] = "Réforme de fond : le seuil initial de douze mois, déjà retiré dans le brouillon, reste supprimé ; la seconde passe retire aussi l'exclusion liée à l'initiative du bénéficiaire dans la rupture. Cette exclusion peut interrompre une qualification alors que l'accord collectif définit déjà les modalités de prise en charge. Le plafond de six mois et la faculté conventionnelle de financement sont maintenus : aucun droit automatique à une dépense ni aucun taux nouveau ne sont institués. La durée pédagogique est coordonnée au contrat unique sans terme d'emploi."
answers[0]['review_notes'] = "Les deux restrictions supprimées figurent dans la seule phrase de la source officielle. L. 6325-11 et L. 6325-13, fournis dans reference-targets.json, portent sur l'action et les enseignements, pas sur une échéance d'emploi. La limite de six mois reste une limite de continuation ; elle ne correspond ni au préavis ni au plafond d'indemnité de rupture. L. 6332-14 II, lu dans le corpus, conserve une énumération distincte de ruptures pour les prises en charge de l'opérateur : son 1° doit être coordonné expressément pour permettre le financement des extensions conventionnelles ici ouvertes, sans prétendre le modifier dans ce lot. Les accords d'application doivent écarter les deux exclusions, sans réouverture des financements achevés ni remise à zéro des six mois. Les prises en charge autonomes plus favorables ne sont pas plafonnées par ce seul article. Aucun gain budgétaire n'est chiffré."
reduction(0, ["Suppression de la durée initiale minimale de douze mois conditionnant l'accès à la continuation conventionnelle de formation.", "Suppression de l'exclusion des bénéficiaires ayant pris l'initiative de la rupture de leur contrat de professionnalisation."])
impact(0, 'material_reduction', "Par rapport à la source entière, deux conditions d'accès disparaissent : action initiale d'au moins douze mois et rupture non voulue. Le brouillon retirait déjà la première ; la seconde passe ouvre aussi le dispositif après départ volontaire. Il s'agit d'une extension d'accès à un avantage conventionnel, sans suppression de prélèvement.", "Le financement demeure conventionnel, limité ici à six mois. L'articulation de L. 6332-14 II avec les nouvelles ruptures éligibles reste à rédiger hors du lot ; aucun montant de prise en charge ni effet net sur les finances publiques n'est établi.", "Aucune charge nouvelle obligatoire n'est identifiée : pas de dossier, attestation, délai ou cotisation de remplacement. La possibilité de financer davantage de bénéficiaires peut accroître les dépenses des dispositifs conventionnels ; leur solde n'est pas chiffré.", [effect('relief_extended', 'professionnalisation-continuation-apres-rupture', "Élargissement de l'accès à la poursuite conventionnelle de formation après rupture.", "Action initiale d'au moins douze mois et rupture sans initiative du bénéficiaire ; continuation conventionnelle de six mois au plus.", "Toute durée initiale et toute initiative de rupture ; continuation conventionnelle toujours limitée à six mois.", 'regime', "Personnes dont le contrat de professionnalisation est rompu, y compris les futurs bénéficiaires en contrat unique.", "Continuations nouvelles et restant à courir dès l'entrée en vigueur ; financements acquis conservés ; pas de nouveau délai de six mois pour une continuation en cours.", "Aucune formalité substitutive ; éventuelle dépense conventionnelle supplémentaire non évaluée.", "d'une durée minimale de douze mois et a été rompu sans que ces personnes soient à l'initiative de cette rupture.", "quelle que soit la durée initialement prévue pour cette action et quelle que soit la partie à l'initiative de la rupture.")])

old = "<p>I.-Une partie de l'action de professionnalisation peut être effectuée à l'étranger. Cette mobilité ne peut excéder un an ni la moitié de la durée totale de l'action de professionnalisation. La durée de cette action peut être portée à vingt-quatre mois, sans préjudice des allongements plus favorables applicables à certains bénéficiaires. Pour les contrats uniques à durée indéterminée, ces durées ne limitent pas celle de l'emploi.</p>"
new = "<p>I.-Une partie de l'action de professionnalisation peut être effectuée à l'étranger. Cette mobilité ne peut excéder un an. Aucune limite calculée en fonction de la moitié de la durée du contrat ou de l'action de professionnalisation ne lui est opposable.</p>\n<p>La durée de l'action de professionnalisation peut être portée à vingt-quatre mois, sans préjudice des allongements plus favorables applicables à certains bénéficiaires. Pour les contrats uniques à durée indéterminée, ces durées ne limitent pas celle de l'emploi.</p>"
assert old in answers[1]['proposed_xml']
answers[1]['proposed_xml'] = answers[1]['proposed_xml'].replace(old, new)
old = "<p>La simplification documentaire s'applique aux mobilités organisées à compter de l'entrée en vigueur de la présente réforme. Les conventions déjà conclues et les garanties déjà acquises demeurent valables. Pour les contrats à durée déterminée conclus avant la loi instituant le contrat unique, les limites d'un an et de la moitié de la durée totale du contrat ainsi que la faculté de porter ce contrat à vingt-quatre mois restent régies par les règles antérieures, sans autoriser un nouveau contrat à terme ou son renouvellement à terme après cette loi.</p>"
new = "<p>La simplification documentaire et la suppression de la limite de moitié s'appliquent aux mobilités organisées à compter de l'entrée en vigueur de la loi portant la présente réforme, y compris au titre d'un contrat antérieur. Les conventions déjà conclues et les garanties acquises demeurent valables ; les parties peuvent convenir d'appliquer ces allègements aux mobilités en cours, sans nouveau dossier reproduisant les stipulations conservées. Les contrats à durée déterminée conclus avant l'entrée en vigueur de la loi instituant le contrat unique conservent leur terme et leurs droits antérieurs. L'allongement d'une action de professionnalisation ne permet ni un nouveau contrat à durée déterminée ni un renouvellement à durée déterminée après cette entrée en vigueur.</p>"
assert old in answers[1]['proposed_xml']
answers[1]['proposed_xml'] = answers[1]['proposed_xml'].replace(old, new)
answers[1]['reason'] = "Réforme de fond : outre le réemploi conventionnel conservé du brouillon, suppression du plafond relatif de la moitié du contrat ou de l'action. Le plafond absolu d'un an, les obligations de sécurité, d'accueil et de couverture sociale assurent des fonctions distinctes ; la restriction de moitié n'apporte pas de protection supplémentaire démontrée et ferme inutilement certaines mobilités courtes. L'allongement à vingt-quatre mois porte désormais sur l'action pédagogique, sans diminuer les prolongations plus favorables. Les conventions peuvent incorporer des stipulations existantes au lieu de les répéter ; le consentement de chaque signataire requis reste indispensable."
answers[1]['review_notes'] = "Conservation des I, II, 1°, 2° et III et du premier alinéa du II comme cible des dérogations de signature. L. 6325-13 demeure inapplicable pendant la mobilité ; ses minima ne sont donc pas réintroduits par le dossier commun. Le plafond d'un an demeure, tandis que la moitié est expressément retirée pour les futures mobilités, y compris sous ancien contrat. Vingt-quatre mois ne fixe aucun terme à l'emploi nouveau ; l'allongement jusqu'à trente-six mois de L. 6325-11 pour le public de L. 6325-1-1 demeure plus favorable. Les anciens termes ne peuvent être prolongés par un renouvellement de CDD après la réforme. Les responsabilités de la structure d'accueil, l'exception au statut salarié, les cinq branches de couverture citées et l'assurance volontaire hors Union sous réserve des règlements et conventions sont conservées. L. 6332-14 I 3° et II 3°, lus dans le corpus, portent sur les frais, pertes de ressources et cotisations de mobilité : ils ne garantissent pas automatiquement le financement de toute durée désormais permise. Coordonner la partie réglementaire de la mobilité et les modèles de conventions pour retirer la moitié et admettre l'incorporation acceptée ; les textes européens et conventions internationales ne sont pas fournis intégralement et ne sont pas déclarés audités. Aucune nouvelle exonération internationale n'est inférée."
answers[1]['benefit_review'] = "La faculté de mobilité et son allongement pédagogique à vingt-quatre mois restent ouverts pour les futures situations recevables ; les allongements plus favorables, notamment jusqu'à trente-six mois, ne sont pas réduits. La dispense d'application de L. 6325-13 à l'étranger subsiste. Les deux voies de signature simplifiée du II et du III restent utilisables, de même que la mise à disposition ou la mise en veille. L'incorporation acceptée évite de répéter un partenariat sans retirer les garanties équivalentes d'accueil. La couverture française lorsque le statut salarié fait défaut dans l'État d'accueil et l'assurance volontaire hors Union demeurent dans leur champ, avec les réserves européennes et internationales. Aucun de ces avantages n'est réservé au stock de contrats ; la limite de moitié est en outre supprimée pour les mobilités nouvelles. Le plafond d'un an est une limite à la mobilité, pas une exonération, et reste conservé."
reduction(1, ["Suppression de la limite de mobilité égale à la moitié de la durée totale du contrat ou de l'action de professionnalisation.", "Suppression de l'obligation de reproduire dans une convention autonome les stipulations exactes et à jour d'un partenariat déjà applicable, lorsqu'un renvoi écrit est accepté par tous les signataires requis."])
impact(1, 'material_reduction', "La source officielle cumulait un an et la moitié du contrat. La seconde passe retire la seconde limite. Elle conserve le gain du brouillon sur la répétition des stipulations conventionnelles, sans compter la seule réutilisation de pièces comme une nouvelle suppression générale de formalités.", "Le plafond absolu d'un an, le consentement, les garanties d'accueil et la couverture sociale restent applicables. Les coûts de mobilité et de financement ne sont pas évalués ; les coordinations réglementaires et internationales ne sont pas réputées achevées.", "Aucune charge nouvelle obligatoire n'est identifiée : le renvoi écrit est une façon facultative de former l'accord déjà requis, sans signataire supplémentaire ni nouvelle déclaration. L'élargissement de durée peut avoir un coût de prise en charge, sans financement automatique institué.", [effect('relief_extended', 'professionnalisation-mobilite-sans-plafond-moitie', "Retrait d'un plafond relatif de durée de mobilité internationale.", "Mobilité limitée à un an et à la moitié de la durée totale du contrat de professionnalisation.", "Mobilité limitée à un an, sans plafond de moitié ; durée de l'action distincte de l'emploi à durée indéterminée.", 'other', "Bénéficiaires de la professionnalisation en mobilité, sous contrats nouveaux ou antérieurs.", "Mobilités organisées après l'entrée en vigueur ; option convenue pour celles en cours, droits acquis conservés.", "Aucune démarche de substitution ; conditions de sécurité et de couverture conservées.", "pour une durée qui ne peut excéder un an ni la moitié de la durée totale du contrat.", "Cette mobilité ne peut excéder un an. Aucune limite calculée en fonction de la moitié de la durée du contrat ou de l'action de professionnalisation ne lui est opposable."), effect('obligation_merged', 'professionnalisation-mobilite-convention-unique', "Incorporation acceptée des stipulations déjà applicables au lieu d'une convention qui les répète.", "Une convention de mobilité est requise, avec les dérogations de signataires du II et du III ; pas de mécanisme exprès d'incorporation prévu par cet article.", "Les mêmes signataires peuvent accepter un renvoi écrit aux stipulations exactes et à jour ; seules les modalités individuelles manquantes sont complétées.", 'legal_duty', "Parties à la professionnalisation, organismes de formation et structures d'accueil concernés.", "Futures mobilités et option convenue pour les mobilités en cours ; conventions et garanties antérieures préservées.", "Consentement et contenu utile déjà requis demeurent ; pas de convention autonome supplémentaire ni d'accès nouveau aux données.", "Les conditions de mise en œuvre de la mobilité du bénéficiaire du contrat de professionnalisation à l'étranger sont prévues par une convention", "Il n'est exigé ni nouvelle convention autonome reproduisant ces stipulations, ni nouvelle remise des pièces déjà légalement accessibles aux signataires.")])

answers[2].update(proposed_xml=None, status='retained_unchanged', reason="Maintien intégral nécessaire après examen : cet article répartit le concours au financement de la rémunération des stagiaires sans instituer un prélèvement, un taux, un dépôt ou un agrément autonome. Retirer un financeur ne simplifierait pas une démarche et risquerait de réduire le financement de la rémunération. Le brouillon remplaçait seulement des mots et nommait France Travail ; cette modification stylistique n'est pas conservée comme une réécriture. Le renvoi fonctionnel à l'institution de L. 5312-1 reste intelligible et exact.", review_notes="L. 5312-1 a été lu dans le corpus : il désigne l'opérateur France Travail ; le mot institution ne crée pas un organisme concurrent. L. 5427-1, également lu, identifie la gestion et le service pour le compte du régime ; son état ABROGE_DIFF dans le corpus appelle une vérification de sa bascule temporelle, sans successeur inventé. L. 1233-68 fourni ici traite du dispositif de sécurisation professionnelle et non d'un contrat de travail. Sa proposition coordonne les périodes de reprise d'emploi au contrat unique et retire un versement patronal pour les nouvelles adhésions ; L. 6341-1 ne rétablit pas ce versement en citant les conditions du dispositif. Aucun gain correspondant n'est recompté ici. Les sources n'établissent aucun double financement automatique à fusionner ; retirer la formule générale de concours ne prouverait pas une baisse de prélèvements. Aucun des renvois n'importe l'ancienneté ou les indemnités de rupture dans la rémunération des stagiaires.")
impact(2, 'retained_necessary', "Maintien de l'intégralité de la source : concours de l'État, des régions, des employeurs, des opérateurs de compétences et de l'institution de l'emploi à la rémunération des stagiaires. Aucune obligation documentaire autonome ou cotisation accessoire supprimable n'est démontrée dans cet article.", "Les modalités et coûts des régimes de rémunération relèvent d'autres textes. Les coordinations de L. 1233-68 et la temporalité de L. 5427-1 ne sont pas achevées par ce maintien ; aucune réduction nette n'est revendiquée.", "Aucune charge nouvelle n'est identifiée puisque le texte officiel est maintenu intégralement, sans nouveau document, registre, condition ou délai. Aucun solde financier de l'ensemble des codes n'est chiffré.", [])

answers[3]['proposed_xml'] = """<p>Le contrat de travail du voyageur, représentant ou placier peut prévoir une période d'essai d'au plus trois mois.</p>
<p>Pour les contrats uniques à durée indéterminée conclus à compter de l'entrée en vigueur de la loi instituant ce contrat, l'essai doit être expressément stipulé et ne peut être renouvelé. Sa rupture est soumise au préavis individuel de quinze jours calendaires de l'une ou l'autre partie, dans les conditions respectivement prévues aux articles L. 1221-25 et L. 1221-26. Le préavis ne prolonge pas l'essai. La fraction du préavis patronal qui ne peut être exécutée avant le terme de l'essai est indemnisée selon l'article L. 1221-25 ; la poursuite du préavis à l'initiative du salarié après ce terme relève de l'article L. 1221-26 et ne fait pas commencer un second préavis. Les dispenses de préavis plus favorables au salarié restent applicables. Un changement de clientèle, d'affectation ou de mission au cours du même contrat n'ouvre pas un nouvel essai.</p>
<p>Les périodes d'essai stipulées dans les contrats conclus auparavant conservent leur régime antérieur et leur limite de trois mois, sans remise à zéro d'une période déjà accomplie.</p>"""
answers[3]['reason'] = "Coordination nécessaire, sans baisse revendiquée du maximum de l'essai : la source fixait déjà trois mois. L'absence de renouvellement du contrat unique est conservée, avec la stipulation expresse et la prise en compte de l'essai accompli. La seconde passe précise les deux fins de préavis : compensation patronale à la limite de l'essai, mais poursuite en démission de la fraction salariale après cette limite selon L. 1221-26. Supprimer cette articulation laisserait un renvoi incohérent aux propositions fournies. Ni la première année ni la fin d'une mission ne deviennent un nouvel essai."
answers[3]['review_notes'] = "L. 1221-25 proposé permet pour l'employeur en essai tout moyen établissant la réception, avec décompte à partir du lendemain ; il n'impose pas la lettre recommandée de licenciement. L. 1221-26 proposé renvoie à la notification écrite du salarié de L. 1234-3 et traite la fraction postérieure à l'essai en démission sans second délai. Le reliquat patronal couvre salaires, avantages et congés, sans prolonger l'ancienneté effective au-delà du terme de l'essai ; ne pas le confondre avec l'indemnité ordinaire. Le maximum de trois mois des VRP n'est pas diminué par la proposition. Le préavis de quinze jours peut être plus long que les anciennes prévenances de droit commun : aucun gain net général n'est prétendu. L. 1221-19, L. 1221-21 à L. 1221-23 ont aussi été lus dans le corpus ; les durées plus courtes et stipulations favorables ne sont pas transformées en essai automatique de trois mois. Les procédures collectives et protections spéciales ne disparaissent pas du seul fait de ce préavis individuel."
impact(3, 'coordination_only', "La source entière permettait déjà un essai d'au plus trois mois : aucune baisse de ce maximum n'est démontrée ici. La proposition coordonne le régime spécial des VRP au contrat unique et à ses deux régimes de notification et de fin d'essai ; l'interdiction de renouvellement ne doit pas être comptée comme une seconde réduction autonome.", "Anciens contrats sous leur régime ; l'effet concret du délai de quinze jours dépend du délai auparavant applicable au salarié concerné. Ni le coût net de rupture ni un solde global de simplification ne sont établis.", "La notification et le préavis de quinze jours sont explicités en exécution de la réforme générale, sans préavis supplémentaire cumulé. Ils peuvent allonger la prévenance de certaines ruptures d'essai, notamment salariales ; ce n'est pas un allègement uniforme. Aucun registre ni dépôt nouveau n'est créé.", [effect('coordination', 'travail-essai-contrat-unique', "Coordination de l'essai spécial des VRP avec l'essai non renouvelable et les préavis du contrat unique.", "Essai facultatif de trois mois au plus dans l'article spécial, sans régime propre de notification décrit dans sa phrase.", "Même maximum de trois mois, sans renouvellement pour les nouveaux contrats ; préavis régi par L. 1221-25 et L. 1221-26.", 'regime', "Voyageurs, représentants et placiers relevant du contrat unique de droit privé.", "Nouveaux contrats seulement pour le régime nouveau ; essais antérieurs et périodes déjà accomplies préservés.", "Notification et quinze jours issus de la mesure générale, pas de deuxième délai ; incidence potentiellement plus contraignante pour certains départs en essai.", "Le contrat de travail peut comporter une période d'essai dont la durée ne peut être supérieure à trois mois.", "Sa rupture est soumise au préavis individuel de quinze jours calendaires de l'une ou l'autre partie, dans les conditions respectivement prévues aux articles L. 1221-25 et L. 1221-26.")])

answers[4]['proposed_xml'] = answers[4]['proposed_xml'].replace("Le voyage de retour ne prolonge pas ce préavis", "Le délai est calculé dans les conditions de l'article L. 1234-3. Le voyage de retour ne prolonge pas ce préavis")
answers[4]['reason'] += " La seconde passe ne retire pas la rémunération spéciale du retour : ce serait supprimer un avantage expressément protégé. Elle précise le point de départ du délai par le renvoi fourni à L. 1234-3 ; aucun document de voyage supplémentaire n'est exigé."
answers[4]['review_notes'] += " Renvoi ajouté à L. 1234-3, cible fournie : quinze jours à compter du lendemain de la présentation ou réception selon le mode légal de notification, et non dès l'envoi. Le montant de la garantie est la rémunération de la durée normale du retour, sans forfait de frais inventé ; la transformation en paiement séparé est recensée comme modalité de charge, avec solde net non évalué."
reduction(4, ["Suppression de l'allongement du préavis individuel des nouveaux contrats de VRP employés hors de France par la durée normale du voyage de retour, sans suppression de la garantie de rémunération correspondante."])
impact(4, 'mixed', "La source allongeait le préavis du temps normal de retour. Pour les nouveaux contrats, cet allongement cesse ; la garantie salariale correspondante devient une indemnisation distincte à la charge de l'employeur. Le salarié n'a plus à prolonger le service pour ce motif. Ce n'est ni une suppression de cette dépense salariale ni une baisse de prélèvement.", "Les contrats antérieurs conservent l'augmentation du délai. La durée du voyage varie ; aucun nombre uniforme de jours économisés ni solde monétaire net n'est établi. Les procédures et autorisations distinctes demeurent.", "Une obligation expresse de paiement séparé remplace la composante salariale du préavis prolongé ; elle est recensée et non comptée comme économie. Aucun justificatif, registre ou déclaration de remplacement n'est institué. Le calcul individuel du retour demeure nécessaire.", [effect('deadline_reduced', 'travail-preavis-individuel-quinze-jours', "Retrait de la prolongation de service pour le retour en France, dans la coordination du préavis unique.", "Préavis applicable au VRP augmenté de la durée normale du voyage lorsque la rupture entraîne le retour en France.", "Quinze jours calendaires pour les nouveaux contrats, sans ajout du voyage ; rémunération spéciale du voyage conservée séparément.", 'calendar_days', "VRP employés hors de France dont la rupture entraîne le retour en France.", "Contrats conclus après la loi instituant le contrat unique ; régime antérieur conservé pour les contrats précédents.", "Indemnisation patronale distincte égale à la rémunération de la durée normale de retour, quelle que soit l'initiative de la rupture.", "La durée du préavis du voyageur, représentant ou placier employé hors de France est augmentée de la durée normale du voyage de retour", "Le voyage de retour ne prolonge pas ce préavis et le salarié n'est pas tenu de rester au service de l'employeur au-delà de ces quinze jours pour ce seul motif."), effect('obligation_added', 'travail-vrp-garantie-remuneration-retour', "Formalisation d'une indemnisation autonome préservant le bénéfice salarial du retour.", "Allongement du préavis par le voyage ; cet article ne prévoyait pas de paiement autonome hors durée d'emploi.", "Paiement patronal de la rémunération correspondant au voyage en sus du préavis de quinze jours, sans ancienneté minimale ni plafond de l'indemnité ordinaire.", 'legal_duty', "Employeurs de VRP nouveaux contrats exercés à l'étranger et salariés revenant en France à la rupture.", "Nouveaux contrats, rupture patronale ou salariale ; anciens contrats sous la règle d'allongement.", "Charge de paiement séparé remplaçant la rémunération de la prolongation ; coût net non établi, aucun forfait nouveau.", "lorsque la rupture du contrat entraîne son retour en France.", "le salarié conserve, en sus des sommes dues au titre du préavis, une indemnisation égale à la rémunération qu'il aurait perçue pendant la durée normale du voyage de retour.")])

answers[5].update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope="Suppression prospective de la branche spéciale d'ouverture de l'indemnité de clientèle liée à un nouveau CDD de VRP ou à son non-renouvellement ; droits des anciens CDD et régime spécial des emplois à durée indéterminée intégralement préservés.")
answers[5]['reason'] += " La seconde passe confirme qu'il n'existe ici ni prélèvement ni formalité à supprimer davantage : le contenu est une garantie indemnitaire. L'abrogation future coordonne la fin des CDD et ne constitue pas une économie de l'indemnité de clientèle."
answers[5]['review_notes'] += " Le renvoi ajouté à L. 7313-13 ne figure pas parmi les cibles requises du fichier de vues ; son texte officiel entier a été lu dans le corpus fourni. Ce fondement est autonome pour le contrat à durée indéterminée et aucune condition d'un an ni aucun plafond de six mois ne doit lui être ajouté. Le terme ou non-renouvellement postérieur d'un ancien CDD reste expressément couvert."
impact(5, 'coordination_only', "La source entière ouvre une indemnité spéciale dans deux situations de CDD. La proposition retire uniquement cette branche pour des contrats futurs désormais interdits, conserve les créances des anciens CDD et renvoie le contrat unique au régime d'indemnité de clientèle du CDI. Aucune indemnité effectivement due n'est supprimée.", "Pas d'économie propre à cet article établie ; le droit de clientèle du CDI et les règles de non-cumul gardent leur objet autonome. L. 7313-13 a été consulté dans le corpus mais ne constitue pas une cible imposée de reference_checks.", "Aucune charge nouvelle n'est identifiée : ni barème, ni déclaration, ni condition d'ancienneté nouvelle. La garantie ancienne continue même pour un terme futur ; le renvoi au CDI n'institue pas une seconde indemnité de même objet.", [effect('coordination', 'travail-contrat-unique-sans-cdd', "Extinction prospective de la branche CDD de la garantie de clientèle, droits anciens sauvegardés.", "Indemnité de clientèle en l'absence de faute grave pour rupture patronale avant terme ou non-renouvellement à l'échéance d'un CDD de VRP.", "Mêmes droits pour les anciens CDD, même après la réforme ; contrats uniques futurs sous L. 7313-13, sans possibilité de nouveau CDD.", 'regime', "VRP sous ancien CDD ou recrutés à l'avenir en contrat unique.", "Application de l'abrogation aux contrats conclus à compter de la loi ; créances et recours anciens conservés.", "Aucune formalité ou indemnité de remplacement créée ; le régime CDI d'indemnité de clientèle subsiste.", "L'indemnité de clientèle est due en cas de rupture du contrat de travail à durée déterminée par l'employeur avant l'échéance du terme", "Pour les nouveaux contrats uniques à durée indéterminée, le droit à l'indemnité de clientèle relève de l'article L. 7313-13.")])

answers[6]['reason'] += " Aucune coupe supplémentaire n'est justifiée : confondre ces objets avec l'indemnité ordinaire retirerait des réparations expressément préservées. La coordination temporelle du brouillon est conservée, sans lui attribuer une baisse de charge."
answers[6]['review_notes'] += " Le renvoi ajouté à L. 7313-13 est extérieur à la liste des cibles requises mais son texte officiel a été lu dans le corpus, ainsi que L. 7313-16. Aucune indemnité forfaitaire de clientèle ni double réparation d'un même préjudice ne résulte de cette distinction d'objets."
impact(6, 'coordination_only', "La distinction complète de la source entre clientèle, rupture abusive du CDI et rupture anticipée du CDD est conservée. Le changement borne la branche CDD aux contrats antérieurs et garantit que le contrat unique ne neutralise ni l'indemnité spéciale ni les dommages d'une illégalité dès le premier jour.", "Aucune réduction normative de coût n'est démontrée dans cet article ; il ne décide pas de tous les cumuls et ne remplace ni L. 7313-13 ni les règles de responsabilité et de réparation.", "Aucune charge nouvelle n'est identifiée : aucun paiement forfaitaire supplémentaire, aucune formalité ou condition nouvelle ; les indemnités de causes distinctes gardent leurs règles propres et ne sont pas automatiquement cumulées pour un même objet.", [effect('coordination', 'travail-contrat-unique-sans-cdd', "Coordination des objets indemnitaires avec le maintien des seuls CDD anciens.", "Clientèle distincte des réparations de rupture abusive du CDI et de rupture anticipée du CDD.", "Même distinction ; la branche CDD vise les contrats antérieurs, et le contrat unique conserve les réparations de rupture illégale sans seuil d'un an.", 'regime', "VRP bénéficiaires de garanties de clientèle ou victimes de rupture illégale.", "Contrats anciens et créances préservés ; nouveau contrat unique sans nouvelle possibilité de CDD.", "Aucune procédure ou indemnité autonome ajoutée ; pas de double compte de préjudices identiques.", "L'indemnité de clientèle ne se confond ni avec l'indemnité pour rupture abusive du contrat de travail à durée indéterminée", "Ni le préavis individuel de quinze jours calendaires ni les conditions de l'indemnité ordinaire de rupture ne suppriment la réparation d'une rupture illégale, y compris avant un an d'ancienneté.")])

answers[7]['proposed_xml'] = answers[7]['proposed_xml'].replace("L'employeur indemnise la fraction de son préavis qui ne peut être exécutée avant la fin de l'essai.", "L'employeur indemnise la fraction de son préavis qui ne peut être exécutée avant la fin de l'essai, dans les conditions de l'article L. 1221-25. La notification, le calcul du délai et, lorsque le salarié prend l'initiative de la rupture, la fraction de préavis exécutée après l'essai relèvent respectivement des articles L. 1221-25 et L. 1221-26, sans second préavis. Les dispenses de préavis plus favorables au salarié demeurent applicables.")
answers[7]['proposed_xml'] = answers[7]['proposed_xml'].replace("La notification, le calcul du délai et, lorsque le salarié prend l'initiative de la rupture, la fraction de préavis exécutée après l'essai relèvent respectivement des articles L. 1221-25 et L. 1221-26, sans second préavis.", "La notification et le calcul du délai relèvent de l'article L. 1221-25 lorsque l'employeur prend l'initiative de la rupture, et de l'article L. 1221-26 lorsque le salarié en prend l'initiative. Dans ce dernier cas, la fraction de préavis exécutée après le terme de l'essai relève de l'article L. 1221-26, sans second préavis.")
answers[7]['reason'] += " La seconde passe ne supprime ni la stipulation expresse ni la déduction des contrats préalables : la première permet de connaître l'essai, la seconde est favorable au salarié. Elle explicite les renvois de fin d'essai pour éviter d'arrêter à tort le préavis du salarié ou de prolonger l'essai patronal."
answers[7]['review_notes'] += " Les renvois nouveaux à L. 1221-25 et L. 1221-26 sont fournis parmi les cibles requises. La fraction patronale indemnisée ne prolonge pas l'ancienneté au-delà du terme d'essai ; la fraction exécutée par le salarié après l'essai vaut démission selon L. 1221-26. Le passage de huit à trois mois réduit un maximum d'essai, pas un taux de cotisation ni une durée garantie d'emploi. Le préavis nouveau peut être plus contraignant que les prévenances antérieures ; cet effet de la mesure générale n'est pas masqué."
reduction(7, ["Suppression de la possibilité d'une période d'essai renouvelable pouvant atteindre huit mois pour les nouveaux contrats d'entrepreneur salarié, au profit de trois mois au plus sans renouvellement."])
impact(7, 'mixed', "Par rapport à la source entière, le maximum d'essai des nouveaux entrepreneurs salariés passe de huit mois renouvellement compris à trois mois sans renouvellement ; les durées des contrats antérieurs à déduire restent intégrales. Le délai de rupture de quinze jours issu de la réforme générale peut simultanément accroître la contrainte de départ en essai. Le solde net n'est pas établi.", "Les contrats conclus avant la loi conservent le maximum ancien et la déduction favorable. Les effets financiers des préavis et les règles du CAPE hors corpus ne sont pas chiffrés ni présentés comme réécrits.", "La stipulation expresse et le préavis de quinze jours sont coordonnés au droit commun proposé, sans registre ni renouvellement d'essai ajouté. Le préavis salarial peut dépasser les anciennes vingt-quatre ou quarante-huit heures de L. 1221-26 ; cette contrainte nouvelle de la mesure générale reste identifiée, sans deuxième décompte de son coût.", [effect('regime_merged', 'travail-essai-contrat-unique', "Alignement du maximum spécial d'essai sur trois mois non renouvelables.", "Pour le contrat d'entrepreneur salarié, maximum de huit mois renouvellement compris, diminué des contrats préalables entre les parties.", "Pour les nouveaux contrats, maximum de trois mois sans renouvellement, diminué des mêmes durées préalables ; aucun essai si la déduction l'épuise.", 'other', "Entrepreneurs salariés de coopératives d'activité et d'emploi recrutés après la réforme.", "Nouveaux contrats uniquement ; essais et périodes antérieures préservés, aucune remise à zéro à un changement d'activité.", "Préavis de quinze jours des deux côtés issu de la mesure générale ; il peut allonger la prévenance de certains départs, sans prolonger l'essai.", "la durée, renouvellement compris, ne peut excéder huit mois.", "une période d'essai peut être expressément stipulée pour trois mois au plus, sans renouvellement."), effect('relief_preserved', 'travail-essai-deduction-contrats-prealables', "Maintien de la déduction favorable du CAPE et de tout autre contrat préalable.", "La durée du contrat d'appui ou de tout autre contrat préalablement conclu entre les parties est déduite du maximum d'essai.", "Même déduction, sur le maximum applicable de trois ou huit mois ; elle n'ouvre jamais un essai négatif ou nouveau.", 'regime', "Entrepreneurs salariés ayant conclu auparavant un contrat avec la coopérative.", "Anciens et nouveaux contrats ; périodes déjà accomplies conservées.", "Aucune condition d'identité d'activité ni attestation nouvelle ajoutée.", "la durée de ces contrats est déduite de la durée prévue au premier alinéa du présent article.", "la durée de ces contrats est déduite de la durée d'essai applicable en vertu du premier alinéa.")])

answers[8]['proposed_xml'] = """<p>Dans les entreprises d'au moins trois cents salariés, les informations trimestrielles prévues au 3° de l'article L. 2312-69 présentent l'évolution des effectifs et de la qualification des salariés par sexe, par comparaison entre la fin du trimestre précédent et la fin du trimestre concerné, sans ventilation mensuelle obligatoire. Elles indiquent :</p>
<p>1° Le nombre de salariés titulaires d'un contrat à durée indéterminée, y compris d'un contrat unique ;</p>
<p>2° Le nombre de salariés titulaires d'un contrat à durée déterminée conclu avant l'entrée en vigueur de la loi instituant le contrat unique et demeurant en cours ; pour les périodes antérieures à cette entrée en vigueur, le nombre de salariés alors titulaires de tels contrats ;</p>
<p>3° Le nombre de salariés à temps partiel ;</p>
<p>4° Le nombre de salariés temporaires, y compris ceux employés à durée indéterminée par l'entreprise de travail temporaire ;</p>
<p>5° Le nombre de salariés appartenant à une entreprise extérieure ;</p>
<p>6° Le nombre de contrats de professionnalisation.</p>
<p>L'employeur présente au comité les motifs de recours aux catégories mentionnées aux 2° à 5°. Lorsque ces motifs ont déjà été communiqués au comité et demeurent inchangés, un renvoi précis à l'information effectivement accessible suffit ; aucune nouvelle présentation des mêmes motifs n'est exigée.</p>
<p>La mise à disposition actualisée des données dans la base de données économiques, sociales et environnementales vaut communication dans les conditions légales. Les données déjà accessibles pour le trimestre sont réutilisées, sans relevé, copie ou envoi supplémentaire. Le présent article n'impose plus le décompte des journées de travail accomplies par les salariés en contrat à durée déterminée et les salariés temporaires au cours de chacun des trois derniers mois. Les décomptes et informations imposés sur un fondement autonome restent régis par leurs dispositions propres.</p>
<p>Les allègements s'appliquent aux informations mises à disposition à compter de l'entrée en vigueur de la loi portant la présente réforme, y compris lorsqu'elles concernent une période antérieure, sans réfection des informations déjà régulièrement communiquées. Les informations historiques demeurent accessibles sous la forme dans laquelle elles ont été communiquées, sans reconstitution d'une ventilation supprimée. Les droits et recours relatifs aux manquements antérieurs demeurent, sous réserve de l'application de la loi répressive plus douce.</p>
<p>Les mentions de contrats à durée déterminée n'autorisent ni nouvelle conclusion ni renouvellement après l'entrée en vigueur du contrat unique. Une durée de mission, de formation ou d'aide ne fixe pas le terme de l'emploi à durée indéterminée et n'impose pas, au titre du 6°, un relevé supplémentaire de ces durées. Les contrats antérieurs et leurs droits acquis conservent leur régime.</p>"""
answers[8]['reason'] = "Réforme de fond : la seconde passe retire la ventilation mensuelle, au-delà du brouillon qui la maintenait ; une comparaison trimestrielle suffit à l'information trimestrielle imposée par L. 2312-69. Les six catégories et la qualification par sexe restent identifiables. La suppression du décompte en journées CDD/intérim et de la répétition de motifs inchangés est conservée. La mise à disposition dans la base valant déjà communication selon L. 2312-18, ce réemploi n'est pas présenté comme une nouvelle réduction autonome. Aucun relevé des durées pédagogiques n'est ajouté."
answers[8]['review_notes'] = "L. 2312-69 et sa note ont été lus intégralement : son 3° exige une évolution des effectifs et de la qualification par sexe chaque trimestre, sans imposer les trois photographies mensuelles. La comparaison des fins de trimestre utilise la photographie déjà donnée au trimestre précédent. Le seuil de trois cents salariés, les 1° à 6° et les motifs de recours nouveaux ou modifiés sont conservés. L. 2312-18 et R. 2312-9 ont été lus dans le corpus : la base vaut déjà communication ; son tableau comporte des obligations autonomes, notamment un nombre moyen mensuel de salariés temporaires. La suppression de ventilation au seul titre de R. 2312-21 ne supprime pas cet indicateur autonome et ne prouve pas la disparition de toute collecte mensuelle. La rubrique 2° reste utile pour le stock et les données historiques, sans nouveau CDD ; 4° inclut le CDI intérimaire, 6° ne fait pas de la formation un terme d'emploi ni une nouvelle donnée obligatoire. Aucune coordination de préavis ou d'indemnité n'est nécessaire dans les chiffres du CSE ; les contrôles et consultations distincts demeurent. Aucun formulaire ni état annuel de protection complémentaire supprimé n'est rétabli."
reduction(8, ["Suppression de la ventilation mois par mois des effectifs et qualifications dans l'information trimestrielle, remplacée par la comparaison des fins de trimestre déjà couvertes par le suivi.", "Suppression du décompte spécifique des journées de travail CDD et intérim pour chacun des trois derniers mois au titre de cet article.", "Suppression de la nouvelle présentation des motifs de recours déjà communiqués au CSE et inchangés, avec maintien d'un accès effectif aux motifs existants."])
impact(8, 'material_reduction', "La source officielle exigeait une ventilation mensuelle et un nombre de journées CDD/intérim pour chacun des trois mois. Ces deux niveaux de détail sont retirés pour cette information trimestrielle ; la répétition des motifs inchangés est également écartée. Le gain de seconde passe est le retrait de la ventilation mensuelle, pas une nouvelle fusion de la base déjà prévue par la loi.", "L'information légale trimestrielle, le seuil de trois cents salariés, les six catégories et la qualification par sexe restent requis. Les indicateurs mensuels autonomes de R. 2312-9 ne disparaissent pas. Le coût net pour l'ensemble des obligations du CSE n'est pas établi.", "Aucune charge nouvelle autonome n'est identifiée : la comparaison entre deux fins de trimestre réutilise les effectifs du suivi existant ; aucun registre, dépôt ni calendrier de remplacement n'est créé. L'accès réel aux motifs précédents remplace leur répétition, sans nouvelle collecte.", [effect('compliance_cost_reduced', 'cse-information-trimestrielle-effectifs-allegee', "Réduction du détail de l'information trimestrielle sur les effectifs.", "Données mois par mois et journées CDD/intérim dans chacun des trois derniers mois, dans les entreprises d'au moins trois cents salariés.", "Comparaison des effectifs et qualifications par sexe entre fins de trimestre ; suppression du décompte spécifique des journées de travail au titre de cet article.", 'legal_duty', "Employeurs d'au moins trois cents salariés et CSE destinataires de l'information.", "Informations communiquées après l'entrée en vigueur, y compris sur périodes antérieures ; pas de réfection des documents déjà communiqués.", "Comparaison trimestrielle utilisant le suivi existant ; autres indicateurs autonomes et consultations conservés.", "les informations trimestrielles du comité social et économique prévues au 3° de l'article L. 2312-69 retracent mois par mois, l'évolution des effectifs et de la qualification des salariés par sexe", "par comparaison entre la fin du trimestre précédent et la fin du trimestre concerné, sans ventilation mensuelle obligatoire."), effect('obligation_removed', 'cse-information-trimestrielle-effectifs-allegee', "Suppression de la répétition des motifs de recours inchangés, au sein de la même mesure de reporting.", "Présentation au CSE des motifs ayant conduit aux catégories 2° à 5°, sans dispense expresse pour les motifs inchangés dans cet article.", "Motifs nouveaux ou modifiés présentés ; motifs identiques déjà communiqués accessibles par renvoi précis.", 'legal_duty', "Employeurs et CSE des entreprises d'au moins trois cents salariés.", "Informations mises à disposition après l'entrée en vigueur ; information déjà régulièrement donnée non refaite.", "Renvoi aux seuls motifs effectivement accessibles, sans attestation ni registre nouveau ; pas de suppression du contrôle du recours à ces catégories.", "L'employeur présente au comité les motifs l'ayant conduit à recourir aux catégories de salariés mentionnées aux 2° à 5°.", "Lorsque ces motifs ont déjà été communiqués au comité et demeurent inchangés, un renvoi précis à l'information effectivement accessible suffit ; aucune nouvelle présentation des mêmes motifs n'est exigée.")])

answers[9].update(proposed_xml=None, status='retained_unchanged', reason="Maintien intégral nécessaire : l'inclusion de l'indemnité de fin de mission dans l'assiette des congés protège une créance salariale sans créer de formalité. Le renvoi demeure cohérent lorsque L. 1251-32 est coordonné : il ne vise que l'indemnité effectivement due, notamment sous ancien contrat, et ne crée pas cette indemnité pour une mission d'un emploi nouveau à durée indéterminée. La seconde passe retire la seule reformulation explicative du brouillon, sans annuler une réforme de fond ni diminuer le salaire.", review_notes="L. 1251-32 fourni distingue la règle officielle de dix pour cent de rémunération brute et sa proposition : créances des anciens contrats conservées, mais pas d'indemnité ouverte par la seule fin de mission des nouveaux contrats uniques ; garantie mensuelle de L. 1251-58-3 maintenue dans cette cible. La phrase de D. 3141-8 reste opérante sans nouvelle transition car elle renvoie à l'indemnité prévue, lorsqu'elle est due, quelle que soit sa date de paiement. L. 3141-24 et toutes ses notes ont été lus dans le corpus : dixième, maintien de salaire, prise en compte de certaines périodes à quatre-vingts pour cent, transition du 1er décembre 2009 à 2024, limite de vingt-quatre jours ouvrables et action dans les deux ans ne sont pas modifiés. Le préavis de quinze jours et l'ancienneté d'un an pour l'indemnité ordinaire n'affectent pas l'assiette des congés. Aucun renvoi incohérent ne requiert une nouvelle règle dans ce bref article.")
impact(9, 'retained_necessary', "La source officielle est maintenue intégralement : le complément de salaire de fin de mission, lorsqu'il est dû, reste dans l'assiette des congés payés. Son retrait diminuerait un droit salarial préservé ; la phrase ne crée ni un CDD futur ni une indemnité de fin de mission autonome.", "Aucun gain de simplification ni baisse de prélèvement n'est revendiqué. La transition et le champ de l'indemnité sont portés par L. 1251-32, dont la proposition reste distincte du droit officiel ; L. 3141-24 conserve ses règles et transitions propres.", "Aucune charge nouvelle n'est identifiée : maintien exact de la règle d'assiette, sans nouvelle pièce, déclaration, délai ou condition. L'article n'étend pas aux emplois nouveaux une indemnité non ouverte par la seule fin de leur mission.", [])

answers[10]['reason'] += " La seconde passe maintient le rappel pour les relations finissant avant un an : il conserve la mutualisation pour les emplois brefs, sans autoriser à diminuer les congés déjà dus. Le supprimer alors que le service direct est également possible déplacerait le risque de financement sans preuve d'un allègement net favorable. Aucun nouveau prélèvement n'est supprimé par le simple passage du service de la caisse au service direct de l'employeur."
answers[10]['review_notes'] += " La dispense future est distincte d'une suppression des droits à congés : elle modifie le service et le financement, non leur montant. Les doubles versements à la même caisse sur les mêmes salaires sont exclus, sans assimiler à un remboursement toutes les indemnités déjà payées directement. Les cotisations déjà dues et les droits déjà financés restent servis selon leur régime. Le bénéfice n'est pas fermé aux nouvelles situations par l'absence de nouveaux CDD. Aucun gain national ni économie égale au montant des cotisations non appelées n'est établi, le paiement direct restant à la charge de l'employeur."
answers[10]['review_notes'] += " Le renvoi ajouté à D. 3141-24 n'est pas fourni parmi les cibles de reference-targets.json ; sa source officielle a été lue intégralement dans le corpus. Elle subordonne le recours facultatif à la caisse à l'accord de celle-ci et au paiement des cotisations correspondantes ; ces conditions ne sont pas supprimées par la dispense de déclaration."
reduction(10, ["Suppression de l'enregistrement du contrat et de la date certaine obtenue par cet enregistrement comme conditions spéciales de dispense de déclaration à la caisse.", "Suppression, pour les nouveaux contrats uniques et conversions prévues, de l'obligation de déclaration à la caisse au profit du service direct des congés, sans engagement de durée minimale de l'emploi ni formalité de remplacement."])
impact(10, 'mixed', "La source réservait la dispense aux CDD d'au moins un an enregistrés. L'enregistrement disparaît et la dispense reste ouverte aux anciens bénéficiaires ainsi qu'aux nouveaux contrats uniques et conversions. C'est un retrait de formalité et une extension de dispense, accompagnés d'un service direct et d'un rappel de cotisations avant un an ; aucune baisse équivalente du coût des congés n'est démontrée.", "Autres salariés et établissements hors D. 3141-12 à D. 3141-15 non couverts par l'extension ; anciens contrats sans conversion gardant leur régime. Les droits financés, cotisations déjà dues et rappels subsistent. Le coût net caisse/employeur et le risque de financement ne sont pas évalués.", "Le service direct des congés demeure à la charge de l'employeur dispensé. L'extension s'accompagne d'une règle expresse de rappel si l'emploi nouveau finit avant un an, préavis inclus : cette obligation conditionnelle est recensée, sans nouvelle déclaration de remplacement ni double cotisation à la même caisse sur les mêmes salaires.", [effect('obligation_removed', 'conges-btp-dispense-sans-enregistrement', "Retrait de l'enregistrement obligatoire du contrat pour bénéficier de la dispense.", "CDD d'une durée minimum d'un an ayant acquis date certaine par enregistrement pour échapper à la déclaration à la caisse.", "Anciens CDD d'au moins un an dispensés sans enregistrement ; pas de justificatif spécial de date certaine substitué.", 'legal_duty', "Employeurs et salariés des établissements de D. 3141-12 à D. 3141-15 éligibles à la dispense.", "Formalités après entrée en vigueur ; droits, cotisations et créances antérieurs conservés.", "Aucun agrément, attestation ou déclaration remplaçant l'enregistrement.", "ayant acquis date certaine par enregistrement.", "L'enregistrement du contrat n'est plus exigé pour bénéficier de cette dispense."), effect('relief_extended', 'conges-btp-dispense-sans-enregistrement', "Ouverture de la dispense aux emplois nouveaux à durée indéterminée et aux conversions.", "Dispense limitée par cet article aux CDD d'au moins un an, avec rappel si rupture avant l'année.", "Dispense pour les nouveaux contrats uniques et conversions sans engagement minimal d'emploi ; rappel si fin effective avant une année d'emploi, préavis inclus, ancienneté avant conversion conservée.", 'regime', "Salariés en contrat unique des établissements concernés et employeurs assurant directement les congés.", "Nouveaux contrats et conversions après réforme ; pas de remise à zéro ni de remboursement général des cotisations antérieures.", "Service direct des congés par l'employeur ; maintien du rappel conditionnel et du service des droits déjà financés par la caisse.", "sauf s'ils sont titulaires d'un contrat de travail à durée déterminée, conclu pour une durée minimum d'un an", "Elle n'est soumise ni à un engagement de durée minimale de l'emploi, ni à un enregistrement, un agrément ou une déclaration de remplacement."), effect('financing_transfer', 'conges-btp-dispense-sans-enregistrement', "Service direct des congés des nouveaux bénéficiaires dispensés, sans réduction du droit salarial.", "Pour les salariés qui n'étaient pas dispensés, déclaration à la caisse et service des congés selon le régime des caisses.", "Pour les nouveaux bénéficiaires de la dispense, service direct par l'employeur, avec option de service par la caisse selon D. 3141-24 et rappel conditionnel avant un an.", 'financing', "Employeurs des salariés nouvellement dispensés, salariés et caisses compétentes.", "Droits financés auparavant et cotisations dues préservés ; aucune double cotisation à la même caisse sur les mêmes salaires.", "Charge de paiement direct et rappel conditionnel ; pas d'économie nationale ni de baisse de cotisation globale présumée.", "Les salariés appartenant aux établissements mentionnés aux articles D. 3141-12 à D. 3141-15 sont déclarés par l'employeur à la caisse compétente", "L'employeur assure directement les congés et indemnités des salariés dispensés de déclaration, sans diminution de leurs droits.")])

# La liste technique est conservée dans son texte exact : seule son articulation
# personnelle et temporelle avec le contrat unique est réécrite.
paragraphs = re.findall(r'<p>.*?</p>', sources[11]['source_xml'], flags=re.S)
assert len(paragraphs) == 28
first = "<p>Il est interdit d'affecter aux travaux énumérés ci-dessous les salariés temporaires, y compris ceux employés à durée indéterminée, les salariés titulaires d'un contrat de travail à durée déterminée de droit privé conclu avant l'entrée en vigueur de la loi instituant le contrat unique et demeurant en cours, ainsi que les salariés en contrat unique visés au troisième alinéa de l'article L. 4142-2. L'interdiction porte sur les travaux les exposant aux agents chimiques dangereux ou aux rayonnements ionisants suivants :</p>"
last = """<p>Les exceptions et dérogations prévues aux articles D. 4154-2, D. 4154-3, D. 4154-4 et D. 4154-6 demeurent ouvertes aux situations futures éligibles, y compris aux mises à disposition de salariés temporaires employés à durée indéterminée et aux emplois en contrat unique entrant dans le champ de l'interdiction. Elles ne dispensent pas des mesures de prévention, de formation et de suivi médical légalement requises.</p>
<p>Les contrats de travail à durée déterminée de droit public entrant dans le champ de la présente partie restent soumis à cette interdiction et à ses exceptions et dérogations, quelle que soit leur date de conclusion. La réforme du contrat unique de droit privé ne modifie pas leur régime.</p>
<p>Les anciens contrats à durée déterminée de droit privé conservent ces protections jusqu'à leur terme. Leur conversion en contrat unique ne fait pas disparaître les protections applicables à l'affectation dangereuse en cours. Le seul passage au contrat unique ne rend pas caduque une dérogation régulièrement accordée dont les conditions restent réunies. Une dérogation à l'interdiction d'affectation n'autorise ni la conclusion ni le renouvellement d'un contrat à durée déterminée de droit privé après l'entrée en vigueur du contrat unique. Les manquements antérieurs, les droits à réparation et les recours conservent leur régime.</p>"""
answers[11]['proposed_xml'] = '\n'.join([first] + paragraphs[1:] + [last])
answers[11]['reason'] = "Coordination de sécurité, sans réduction de la liste ni prétention de réécrire ses vingt-sept rubriques conservées textuellement. La seconde passe corrige deux lacunes du brouillon : maintien de la protection pour les futurs emplois de même objet que les anciens CDD, selon le troisième alinéa de L. 4142-2 fourni, et maintien des CDD publics dans le champ de la santé au travail sans condition d'antériorité. Les dérogations favorables futures et autorisations valables restent ouvertes. Retirer des agents dangereux, l'autorisation exceptionnelle ou les mesures médicales réduirait une protection essentielle contre des risques graves, sans doublon démontré dans cet article."
answers[11]['review_notes'] = "Vingt-sept rubriques conservées mot pour mot, avec les exclusions de composés, opérations et seuils : le 23° garde 2 millisieverts intégrés sur une heure et le renvoi au premier groupe du 1° du II de R. 4451-99. Ce dernier, lu dans le corpus, retient un risque de dépassement de 20 millisieverts durant l'urgence, distinct des 2 millisieverts horaires ; aucune substitution de seuil. La rédaction préexistante « retrait ou et de démolition » du 1° est signalée comme maladresse de source et n'est pas corrigée silencieusement. Le renvoi nouveau à L. 4142-2 est une cible fournie : son troisième alinéa maintient les garanties dans les situations correspondant aux anciens L. 1242-2 et L. 1242-3, sans autoriser de CDD ; ces deux sources officielles ont été lues dans le corpus. L. 4154-1 à L. 4154-4, D. 4154-2, D. 4154-4, D. 4154-6 et leurs notes ont été lus dans le corpus. Le premier alinéa de la proposition actuelle de L. 4154-1 ne réserve pas expressément les futurs CDD publics ; il doit être complété sur ce point en coordination avec L. 4111-1 et L. 4111-5, lus, sans les assujettir au contrat privé. Les renvois ajoutés à D. 4154-2, D. 4154-4 et D. 4154-6 ne sont pas des cibles imposées du fichier, mais leurs textes officiels ont été lus ; appareil hermétiquement clos en marche normale, décision en un mois après enquête et retrait motivé par la perte des conditions restent applicables. D. 4154-3 fourni admet la réception à date certaine et réserve les contrats publics ; aucun recommandé exclusif n'est réintroduit ici. Les avis CSE et médicaux, mesures de prévention, formation renforcée et présomption de faute inexcusable restent à leurs champs propres. Les garanties de droit de l'Union et de radioprotection ne sont pas effacées et leur conformité exhaustive n'est pas affirmée. Aucune procédure spéciale de protection ne disparaît avec les quinze jours de préavis."
impact(11, 'coordination_only', "Par rapport à la source entière, les vingt-sept rubriques dangereuses restent intégralement conservées. Le champ est coordonné à l'emploi intérimaire à durée indéterminée, aux futurs emplois de même objet que les anciens CDD selon L. 4142-2, et aux contrats publics encore éligibles. Les dérogations futures demeurent. Aucune réduction de charge de sécurité n'est revendiquée.", "Le lot ne réécrit pas L. 4154-1, dont la proposition doit encore réserver expressément les CDD publics, ni l'ensemble des textes de prévention et du droit de l'Union. Les salariés ordinaires en CDI hors catégories protégées ne sont pas tous ajoutés à la liste. Aucun gain net de complexité n'est démontré.", "L'application aux contrats uniques de même objet rend explicite une interdiction pour certaines futures embauches désormais à durée indéterminée, qui seraient hors champ en raisonnant sur le seul mot CDI : cette contrainte coordonnée de sécurité est recensée sous la mesure commune, pas comptée comme coupe. Aucun registre, avis ou dépôt supplémentaire n'est créé par la liste.", [effect('coordination', 'travail-protection-risques-contrat-unique', "Maintien du champ protecteur et des dérogations malgré la suppression des nouveaux CDD privés.", "Interdiction des vingt-sept catégories de travaux pour les salariés titulaires d'un CDD et les salariés temporaires, avec exceptions et autorisation selon les articles suivants.", "Même liste pour les anciens CDD privés, les temporaires y compris en CDI, les contrats uniques visés au troisième alinéa de L. 4142-2 et les CDD publics relevant de la partie santé au travail ; dérogations futures préservées.", 'regime', "Travailleurs exposés appartenant aux catégories protégées et leurs employeurs, y compris les employeurs publics dans le champ légal.", "Nouvelles situations comparables protégées ; contrats et autorisations antérieurs conservés tant que leurs conditions demeurent ; pas de CDD privé nouveau par dérogation.", "Extension explicite aux nouveaux emplois comparables en CDI, coordonnée à la mesure législative ; aucune nouvelle liste, autorisation ou formalité cumulée dans cet article.", "Il est interdit d'employer des salariés titulaires d'un contrat de travail à durée déterminée et des salariés temporaires", "les salariés temporaires, y compris ceux employés à durée indéterminée, les salariés titulaires d'un contrat de travail à durée déterminée de droit privé conclu avant l'entrée en vigueur de la loi instituant le contrat unique et demeurant en cours, ainsi que les salariés en contrat unique visés au troisième alinéa de l'article L. 4142-2.")])

answers[11]['review_notes'] += " La même réserve expresse pour les CDD publics futurs doit être coordonnée dans L. 4142-2 et les propositions de L. 4154-2 et L. 4154-3 consultées ; leur rédaction limitée aux CDD antérieurs ne doit pas fermer ces garanties de santé au travail. Ces coordinations législatives ne sont pas déclarées achevées par la présente liste réglementaire."

# Analyses individualisées des trois cibles transversales. Les vues fournies
# contiennent des propositions : elles ne sont jamais présentées comme du droit positif.
checks = [{} for _ in sources]
preavis = [
    "L. 6325-14-1 ne renvoie pas au préavis de licenciement : il intervient après une rupture pour prolonger la formation. L. 1234-1 officiel distingue les anciennetés de moins de six mois, six mois à deux ans et deux ans ; sa proposition réserve quinze jours aux nouveaux contrats. Ni la continuation de six mois ni l'extension après départ volontaire ne prolonge ou ne remplace ce préavis.",
    "La mise en veille ou la mise à disposition de L. 6325-25 n'est pas un licenciement. L. 1234-1 proposé substitue quinze jours aux anciens préavis selon ancienneté pour les nouvelles embauches, pas aux limites de mobilité. Un an de mobilité et vingt-quatre mois d'action pédagogique ne sont donc ni une ancienneté d'ouverture ni une prolongation de préavis.",
    "Le financement des stagiaires de L. 6341-1 ne relève pas directement de L. 1234-1. La proposition de ce dernier fixe quinze jours pour les nouveaux contrats et conserve le régime ancien par ancienneté. Cette durée individuelle n'efface ni la procédure économique ni le dispositif de sécurisation professionnelle visé par L. 1233-68 ; aucun versement supprimé dans ce dispositif n'est rétabli ici.",
    "L. 1234-1 porte sur la rupture patronale hors régime propre d'essai ; sa proposition de quinze jours ne suffit pas à régler l'essai des VRP. L. 7313-5 se coordonne donc expressément aux cibles L. 1221-25 et L. 1221-26 pour le préavis d'essai, la compensation patronale et le départ salarial. Les anciens essais de trois mois ne sont pas remplacés par les seuils d'ancienneté du licenciement.",
    "L. 7313-10 est un complément spécial au préavis des VRP, pas une application isolée des un et deux mois de L. 1234-1 officiel. Dans la proposition, quinze jours valent pour le nouveau contrat, sans ancienneté minimale ; le voyage ne les augmente plus mais garde une garantie de rémunération distincte. Le stock de contrats conserve l'augmentation liée au retour et le régime spécial antérieur.",
    "L. 7313-14 ouvre une indemnité de clientèle au terme ou à la rupture d'un ancien CDD ; L. 1234-1 ne convertit pas ces événements en licenciement de CDI avec nouveau préavis. Les contrats uniques futurs relèvent de leurs règles de rupture et de L. 7313-13, sans faire du terme d'un ancien contrat un nouveau délai de quinze jours. Les préavis antérieurs restent à leur champ.",
    "La distinction d'objets indemnitaires de L. 7313-15 ne règle pas le préavis de L. 1234-1. Le délai proposé de quinze jours des contrats nouveaux ne remplace ni les dommages d'une illégalité ni l'indemnité de clientèle ; les seuils d'ancienneté des préavis officiels restent réservés aux contrats antérieurs. Aucun nouveau CDD ni délai de procédure collective n'est créé par cette distinction.",
    "L. 7332-1 traite de l'essai d'un entrepreneur salarié, non du licenciement ordinaire couvert par L. 1234-1. Les quinze jours d'essai sont coordonnés aux cibles L. 1221-25 et L. 1221-26, avec leur notification et leur fin effective propres. Les seuils anciens de six mois et deux ans ne doivent pas fixer une durée d'essai ou neutraliser la déduction des contrats préalables.",
    "L'information du CSE prévue à R. 2312-21 ne renvoie pas à L. 1234-1. Le détail trimestriel peut être réduit sans modifier l'ouverture ou la durée du préavis de chaque salarié. La proposition de quinze jours pour les nouveaux contrats et les anciennes durées selon ancienneté restent donc hors du décompte statistique ; aucune procédure de rupture ne devient facultative par cette réduction de reporting.",
    "D. 3141-8 règle l'assiette des congés, sans renvoi au préavis de licenciement. Les quinze jours proposés dans L. 1234-1 pour les nouveaux contrats et les anciens préavis selon ancienneté ne plafonnent ni l'indemnité de fin de mission effectivement due ni son inclusion dans les congés. La conservation textuelle de l'article ne recrée aucun préavis à la seule fin d'affectation.",
    "La durée d'un an de D. 3141-23 sert au rappel des cotisations de congés ; ce n'est pas un seuil du préavis de L. 1234-1. Pour le contrat unique, la fin effective inclut le préavis applicable de quinze jours, tandis que les anciens contrats gardent leur préavis propre. La dispense ne permet pas d'ignorer le préavis payé ou de prolonger fictivement un essai au-delà de sa fin.",
    "L. 1234-1 ne règle pas l'affectation dangereuse de D. 4154-1. Le préavis privé proposé de quinze jours n'autorise aucun travail interdit et ne supprime ni prévention ni autorisation exceptionnelle. Les contrats publics dans le champ santé au travail restent protégés selon leur régime ; le délai de rupture du contrat unique privé ne leur est pas attribué artificiellement."
]
