for i, s in enumerate(sources):
    key = s['code_id'] + '|' + s['source_id']
    required = refs['requirements'][key]
    expected_numbers = {refs['targets'][t]['number'] for t in required}
    assert set(checks[i]) == expected_numbers, (s['number'], set(checks[i]), expected_numbers)
    answers[i]['reference_checks'] = [dict(target_key=t, view_sha256=refs['targets'][t]['view_sha256'], assessment=checks[i][refs['targets'][t]['number']]) for t in required]

with open('answer.json', 'w') as f:
    json.dump(answers, f, ensure_ascii=False, indent=2)
    f.write('\n')
print('answer.json :', len(answers), 'articles,', sum(len(a['reference_checks']) for a in answers), 'contrôles de renvoi.')
